import { AlertTriangle, RefreshCw } from "lucide-react";
import { Component, type ErrorInfo, type ReactNode } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";

type Props = {
  children: ReactNode;
};

type State = {
  hasError: boolean;
  errorMessage: string;
};

export class ErrorBoundary extends Component<Props, State> {
  state: State = {
    hasError: false,
    errorMessage: "",
  };

  static getDerivedStateFromError(error: Error): State {
    const msg = error.message || "Unexpected error";
    const isChunk = /failed to fetch|load.*module|loading chunk|dynamically imported/i.test(msg);
    if (isChunk && !sessionStorage.getItem("tl_chunk_reload")) {
      sessionStorage.setItem("tl_chunk_reload", "1");
      const url = new URL(window.location.href);
      url.searchParams.set("_r", String(Date.now()));
      window.location.replace(url.toString());
    }
    return { hasError: true, errorMessage: msg };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    console.error("Unhandled UI error:", error, errorInfo);
  }

  reset = () => {
    this.setState({ hasError: false, errorMessage: "" });
  };

  render() {
    if (this.state.hasError) {
      return (
        <div className="container mx-auto flex min-h-[50vh] items-center justify-center px-4 py-10">
          <Card className="w-full max-w-xl border-destructive/40">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-destructive">
                <AlertTriangle className="h-5 w-5" />
                Something went wrong
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <p className="text-sm text-muted-foreground">
                This section crashed unexpectedly. You can retry or refresh the page.
              </p>
              {this.state.errorMessage && (
                <pre className="overflow-auto rounded bg-muted/40 p-2 text-xs text-muted-foreground">
                  {this.state.errorMessage}
                </pre>
              )}
              <div className="flex gap-2">
                <Button onClick={this.reset} className="gap-2">
                  <RefreshCw className="h-4 w-4" />
                  Retry
                </Button>
                <Button variant="outline" onClick={() => window.location.reload()}>
                  Reload page
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>
      );
    }

    return this.props.children;
  }
}
