import { supabase } from "@/integrations/supabase/client";

/** Custom event — pages update React state / query cache only (never window.location.reload). */
export const BACKGROUND_REFRESH_EVENT = "threatlens:background-refresh";
export const BACKGROUND_REFRESH_MS = 10_000;

const PRIORITY_FETCH_NAMES = [
  "BleepingComputer", "The Hacker News", "Dark Reading", "Krebs on Security",
  "SecurityWeek", "The Record", "Cyberscoop", "Snyk Security", "Rapid7 Blog",
  "Socket Security Blog", "JFrog Security Blog", "ReversingLabs Blog",
];

let tick = 0;

/** Fire-and-forget ingest — used only as optional fallback; primary ingest runs on Supabase cron 24/7. */
export function runBackgroundIngest(): void {
  tick++;
  supabase.functions.invoke("fetch-feeds", { body: { names: PRIORITY_FETCH_NAMES } }).catch(() => {});
  supabase.functions.invoke("google-news-agent", { body: {} }).catch(() => {});
  if (tick % 3 === 0) {
    supabase.functions.invoke("ingest-api-feeds", { body: { source: "hackernews" } }).catch(() => {});
  }
  if (tick % 6 === 0) {
    supabase.functions.invoke("site-guardian", { body: {} }).catch(() => {});
  }
}

export function dispatchBackgroundRefresh(): void {
  window.dispatchEvent(new CustomEvent(BACKGROUND_REFRESH_EVENT));
}
