/**
 * ThreatLens — Enterprise Security Layer
 *
 * Covers:
 *  - Content sanitisation (strips all HTML/script from feed data before render)
 *  - Supply-chain attack detection (validates feed data integrity)
 *  - Bot / scanner detection and blocking
 *  - URL allow-list validation (prevents SSRF)
 *  - Rate limiting for outbound requests
 *  - Error sanitisation (no internal details leaked to console)
 */

// ── 1. Content Sanitiser ──────────────────────────────────────────────────────
// Strips every piece of HTML/JS/CSS that could be injected via a compromised
// upstream source. Called on every field before it is stored or rendered.

const DANGEROUS_PATTERNS = [
  /<script[\s\S]*?<\/script>/gi,
  /<iframe[\s\S]*?<\/iframe>/gi,
  /<object[\s\S]*?<\/object>/gi,
  /<embed[\s\S]*?<\/embed>/gi,
  /<link[\s\S]*?>/gi,
  /<base[\s\S]*?>/gi,
  /<meta[\s\S]*?>/gi,
  /javascript\s*:/gi,
  /vbscript\s*:/gi,
  /data\s*:\s*text\s*\/\s*html/gi,
  /on\w+\s*=\s*["'][^"']*["']/gi,   // on* event handlers
  /on\w+\s*=\s*[^>\s]+/gi,
  /expression\s*\(/gi,               // CSS expression()
  /url\s*\(\s*["']?\s*javascript/gi,
  /<[^>]+>/g,                        // strip remaining HTML tags last
];

export function sanitiseText(raw: string | null | undefined): string {
  if (!raw) return "";
  let s = String(raw);
  for (const p of DANGEROUS_PATTERNS) s = s.replace(p, "");
  return s
    .replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&amp;/g, "&")
    .replace(/&#(x[0-9a-f]+|\d+);/gi, "") // strip numeric entities
    .replace(/\s{3,}/g, "  ")
    .trim()
    .slice(0, 4000);
}

export function sanitiseUrl(raw: string | null | undefined): string {
  if (!raw) return "";
  const s = String(raw).trim();
  // Only allow http/https
  if (!/^https?:\/\//i.test(s)) return "";
  // Block data URIs, javascript:, local-network addresses embedded in URL
  if (/javascript:|vbscript:|data:/i.test(s)) return "";
  try {
    const u = new URL(s);
    if (!["http:", "https:"].includes(u.protocol)) return "";
    // Block private/localhost targets (SSRF prevention)
    if (/^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|0\.0\.0\.0|::1|0x|%)/i.test(u.hostname)) return "";
    return s.slice(0, 2000);
  } catch { return ""; }
}

// ── 2. Supply-Chain Attack Detection ─────────────────────────────────────────
// Feed items from compromised upstream sources could carry injected payloads.
// This validates every field before the item is accepted for display.

interface FeedItem {
  title?: unknown;
  link?: unknown;
  excerpt?: unknown;
  source_name?: unknown;
  [key: string]: unknown;
}

const INJECTION_SIGNALS = [
  /<script/i, /javascript:/i, /vbscript:/i, /data:text\/html/i,
  /on\w+\s*=/i, /<iframe/i, /<object/i, /\\�/,
  /\x00/, /&#0*58;/, /&#x0*3A;/, // encoded colon bypass attempts
];

export function isCleanFeedItem(item: FeedItem): boolean {
  if (!item || typeof item !== "object") return false;
  if (typeof item.title !== "string" || item.title.trim().length < 3) return false;
  if (typeof item.link !== "string") return false;
  if (sanitiseUrl(item.link) === "") return false;

  // Check every string field for injection patterns
  for (const [, val] of Object.entries(item)) {
    if (typeof val !== "string") continue;
    for (const p of INJECTION_SIGNALS) {
      if (p.test(val)) return false;
    }
  }
  return true;
}

// ── 3. Outbound URL Allow-List (SSRF prevention) ─────────────────────────────
// Only allow fetching from known-safe domains. Any other domain is blocked.

const ALLOWED_FETCH_DOMAINS = new Set([
  // Threat intel APIs
  "threatfox-api.abuse.ch", "urlhaus-api.abuse.ch", "mb-api.abuse.ch",
  "feodotracker.abuse.ch", "sslbl.abuse.ch",
  "api.greynoise.io", "internetdb.shodan.io",
  "api.first.org", "services.nvd.nist.gov",
  "pulsedive.com", "api.osv.dev",
  "www.cisa.gov",
  "otx.alienvault.com", "api.virustotal.com", "api.abuseipdb.com",
  "api.shodan.io", "haveibeenpwned.com", "api.haveibeenpwned.com",
  // News + search
  "news.google.com", "www.bing.com", "api.duckduckgo.com",
  "api.github.com", "feeds.feedburner.com", "rss.app",
  // CORS proxies
  "corsproxy.io", "api.allorigins.win", "cors.eu.org",
  "thingproxy.freeboard.io", "api.codetabs.com",
  // AI inference providers
  "api.groq.com",
  "text.pollinations.ai", "image.pollinations.ai",
  "api-inference.huggingface.co",
  "api.openai.com",
  // Supabase
  "quxohsplizcyzsnfwijw.supabase.co",
]);

export function isAllowedFetchTarget(url: string): boolean {
  try {
    const u = new URL(url);
    const host = u.hostname.replace(/^www\./, "");
    return ALLOWED_FETCH_DOMAINS.has(host) ||
      [...ALLOWED_FETCH_DOMAINS].some(d => host.endsWith("." + d));
  } catch { return false; }
}

// ── 4. Bot / Scanner Detection ────────────────────────────────────────────────
// Detects headless browsers, vulnerability scanners, and scraping bots.
// Returns true if the visitor looks like an automated client.

const BOT_UA_FRAGMENTS = [
  "bot","crawler","spider","scraper","wget","curl","python-requests","python-urllib",
  "go-http-client","scrapy","httpclient","okhttp","libwww","java/","perl/",
  "nikto","nessus","nmap","masscan","zgrab","nuclei","burp","sqlmap",
  "dirbuster","gobuster","hydra","metasploit","openvas","acunetix","w3af",
  "havij","joomla scanner","wordpress scanner","whatweb","wapiti","skipfish",
  "arachni","zap","vega","dastardly","katana","httpx","subfinder","amass",
  "dnsx","ffuf","feroxbuster","caido","postman","insomnia","httpie",
];

export function isBot(): boolean {
  if (typeof navigator === "undefined") return false;
  const ua = navigator.userAgent.toLowerCase();
  if (!ua || ua.length < 10) return true; // empty UA = bot
  return BOT_UA_FRAGMENTS.some(f => ua.includes(f));
}

// Detects headless Chromium (commonly used for scraping)
// Only uses reliable automation-specific signals to avoid false-positives on
// real users (Firefox/Safari/modern Chrome all lack onbeforeinstallprompt
// and have empty navigator.plugins, so those cannot be used as signals).
export function isHeadlessBrowser(): boolean {
  if (typeof navigator === "undefined" || typeof window === "undefined") return false;
  const tests = [
    // webdriver is explicitly set by Selenium, Playwright, Puppeteer
    () => navigator.webdriver === true,
    // languages empty — real browsers always have at least one language
    () => (navigator as any).languages === undefined || (navigator as any).languages.length === 0,
    // Chrome-headless user agent substring
    () => /headlesschrome/i.test(navigator.userAgent),
    // Phantom.js artifact
    () => typeof (window as any).callPhantom === "function" || typeof (window as any)._phantom !== "undefined",
  ];
  // Need at least 2 reliable signals to flag as headless
  return tests.filter(t => { try { return t(); } catch { return false; } }).length >= 2;
}

// ── 5. Rate Limiter (in-memory, per-key) ─────────────────────────────────────
// Prevents a single session from hammering external APIs.

const rl = new Map<string, { n: number; resetAt: number }>();

export function checkRateLimit(key: string, maxReq: number, windowMs: number): boolean {
  const now = Date.now();
  const e = rl.get(key);
  if (!e || now > e.resetAt) { rl.set(key, { n: 1, resetAt: now + windowMs }); return true; }
  if (e.n >= maxReq) return false;
  e.n++; return true;
}

// ── 6. Error Sanitiser ────────────────────────────────────────────────────────
// Strips stack traces and internal paths from errors shown to the user.

export function sanitiseError(err: unknown): string {
  if (!err) return "An unexpected error occurred.";
  const msg = err instanceof Error ? err.message : String(err);
  // Remove file paths, stack frames, internal module names
  return msg
    .replace(/at\s+\S+\s+\([^)]+\)/g, "")
    .replace(/\/[a-z0-9_/-]+\.(ts|tsx|js|jsx)/gi, "[internal]")
    .replace(/\bsupabase\b/gi, "service")
    .replace(/\bapikey\b/gi, "[redacted]")
    .replace(/\bbearer\b/gi, "[redacted]")
    .replace(/eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]*/g, "[token]")
    .trim()
    .slice(0, 150) || "Operation failed. Please try again.";
}

// ── 7. Frame-bust (anti-clickjacking) ────────────────────────────────────────
// If the page is loaded inside a frame (iframe/object), break out immediately.

export function enforceNoFrame(): void {
  try {
    if (window.self !== window.top) {
      window.top!.location.href = window.self.location.href;
    }
  } catch {
    // Cross-origin frame access denied — just log it, don't navigate away.
    // Navigating to about:blank would wipe the page for legitimate users behind
    // reverse proxies or Docker network bridges.
    console.warn("ThreatLens: running in a cross-origin frame.");
  }
}

// ── 8. Sensitive data masker (for logs / display) ────────────────────────────
export function maskSensitive(s: string): string {
  return s
    .replace(/eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]*/g, "[JWT]")
    .replace(/\b[A-Za-z0-9]{32,}\b/g, (m) => m.slice(0, 6) + "…")
    .replace(/password[^,}"\s]*/gi, "password:[redacted]")
    .replace(/api[_-]?key[^,}"\s]*/gi, "apikey:[redacted]");
}
