import { createContext, useContext, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { isPlatformAdmin, hasThreatIntelAccess } from "@/lib/admin-config";

export type UserRole = "admin" | "user" | null;

interface RoleCtx {
  role: UserRole;
  isAdmin: boolean;
  userEmail: string | null;
}

const RoleContext = createContext<RoleCtx>({ role: null, isAdmin: false, userEmail: null });

export function RoleProvider({ children }: { children: React.ReactNode }) {
  const [role, setRole]           = useState<UserRole>(null);
  const [userEmail, setUserEmail] = useState<string | null>(null);

  function computeRole(email: string | null | undefined): UserRole {
    if (!email) return null;
    return hasThreatIntelAccess(email) ? "admin" : "user";
  }

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      const email = data.session?.user?.email ?? null;
      setUserEmail(email);
      setRole(computeRole(email));
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_, session) => {
      const email = session?.user?.email ?? null;
      setUserEmail(email);
      setRole(computeRole(email));
    });

    return () => subscription.unsubscribe();
  }, []);

  return (
    <RoleContext.Provider value={{ role, isAdmin: isPlatformAdmin(userEmail), userEmail }}>
      {children}
    </RoleContext.Provider>
  );
}

export const useRole = () => useContext(RoleContext);
