import { lazy, type ComponentType, type LazyExoticComponent } from "react";
import { clearAllCaches } from "@/lib/cache-cleanup";

const CHUNK_RELOAD_KEY = "tl_chunk_reload";

function isChunkLoadError(err: unknown): boolean {
  const msg = String((err as Error)?.message ?? err);
  return /failed to fetch|load.*module|loading chunk|dynamically imported|import\(/i.test(msg);
}

/**
 * Wraps React.lazy — on stale CDN chunk mismatch, clears caches and reloads once.
 * Fixes Safari/WebKit "Load failed" / "Importing a module script failed".
 */
export function lazyWithRetry<T extends ComponentType<unknown>>(
  factory: () => Promise<{ default: T }>,
): LazyExoticComponent<T> {
  return lazy(() =>
    factory().catch(async (err) => {
      if (isChunkLoadError(err) && !sessionStorage.getItem(CHUNK_RELOAD_KEY)) {
        sessionStorage.setItem(CHUNK_RELOAD_KEY, "1");
        clearAllCaches();
        if ("caches" in window) {
          const keys = await caches.keys();
          await Promise.all(keys.map((k) => caches.delete(k)));
        }
        if ("serviceWorker" in navigator) {
          const regs = await navigator.serviceWorker.getRegistrations();
          await Promise.all(regs.map((r) => r.unregister()));
        }
        const url = new URL(window.location.href);
        url.searchParams.set("_r", String(Date.now()));
        window.location.replace(url.toString());
        return new Promise<{ default: T }>(() => {});
      }
      throw err;
    }),
  );
}

/** Clear one-shot chunk reload flag after a successful app boot. */
export function clearChunkReloadFlag(): void {
  sessionStorage.removeItem(CHUNK_RELOAD_KEY);
}
